sys_transform_script.script:
(function runTransformScript(source, map, log, target) {
    // Safety: never create or update without the partner record ID
    if (source.u_sender_sys_id.nil()) {
        error = true;
        error_message = 'Remote sync: u_sender_sys_id is empty, row rejected';
        return;
    }
    if (action == 'insert') {
        // Route new work to the provider queue (group sys_id in a property)
        target.assignment_group = gs.getProperty('x_1664823_remote_0.default_assignment_group');
        // Record the customer ticket number and CMDB names once, on creation only
        target.work_notes = 'Created from ' + source.u_sender_system + ' ticket ' + source.u_sender_number +
            '\nCustomer service: ' + source.u_business_service +
            ' / offering: ' + source.u_service_offering +
            ' / CI: ' + source.u_cmdb_ci;
    }
})(source, map, log, target);
